from pathlib import Path

def replace_once(path, old, new):
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    if old not in text:
        raise SystemExit(f"expected block not found in {path}")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")

replace_once("webui/server.py", '    def _configure_data_source(self) -> None:\n        raw = str(self._settings.get("source_project_root") or ".").strip()\n        source = Path(raw).expanduser()\n        if not source.is_absolute():\n            source = self.root / source\n        self.source_root = source.resolve()\n        dataset_root = self.source_root / "datasets" / "failrecovery"\n        manifest = dataset_root / "manifest.jsonl"\n        transitional_manifest = (\n            self.source_root\n            / "datasets"\n            / "lf3r_failure_rollouts"\n            / "failrecovery_manifest.jsonl"\n        )\n        legacy_manifest = (\n            self.source_root\n            / "datasets"\n            / "lf3r_failure_rollouts"\n            / "v1"\n            / "failrecovery_manifest.jsonl"\n        )\n        # New standalone layout is dataset-centric. The two old paths are\n        # read-only compatibility inputs for repositories not migrated yet.\n        if manifest.is_file():\n            self.manifest_path = manifest\n        elif transitional_manifest.is_file():\n            self.manifest_path = transitional_manifest\n        else:\n            self.manifest_path = legacy_manifest\n        self.tactile = FailRecoveryTactileService(self.source_root, self.manifest_path)\n        self._rollouts = None\n        self._rollout_map = None\n', '    def _configure_data_source(self) -> None:\n        raw = str(self._settings.get("source_project_root") or ".").strip()\n        source = Path(raw).expanduser()\n        if not source.is_absolute():\n            source = self.root / source\n        self.source_root = source.resolve()\n\n        dataset_root = self.source_root / "datasets" / "failrecovery"\n        manifest_entry = dataset_root / "manifest.jsonl"\n        transitional_manifest = (\n            self.source_root\n            / "datasets"\n            / "lf3r_failure_rollouts"\n            / "failrecovery_manifest.jsonl"\n        )\n        legacy_manifest = (\n            self.source_root\n            / "datasets"\n            / "lf3r_failure_rollouts"\n            / "v1"\n            / "failrecovery_manifest.jsonl"\n        )\n\n        # The canonical standalone layout may keep manifest.jsonl as a symlink\n        # into the original LF3R repository. Resolve that link, then infer the\n        # root that the manifest\'s historical project-relative paths belong to.\n        if manifest_entry.is_file():\n            self.manifest_path = manifest_entry.resolve()\n        elif transitional_manifest.is_file():\n            self.manifest_path = transitional_manifest.resolve()\n        else:\n            self.manifest_path = legacy_manifest.resolve()\n\n        self.data_root = self._infer_manifest_data_root(\n            self.manifest_path,\n            fallback=self.source_root,\n        )\n        self.tactile = FailRecoveryTactileService(self.data_root, self.manifest_path)\n        self._rollouts = None\n        self._rollout_map = None\n\n    @classmethod\n    def _infer_manifest_data_root(cls, manifest_path: Path, fallback: Path) -> Path:\n        fallback = fallback.resolve()\n        if not manifest_path.is_file():\n            return fallback\n\n        references: list[str] = []\n        try:\n            with manifest_path.open("r", encoding="utf-8") as handle:\n                for line in handle:\n                    if not line.strip():\n                        continue\n                    row = json.loads(line)\n                    if not isinstance(row, dict):\n                        continue\n                    cameras = row.get("camera_video_paths")\n                    if isinstance(cameras, dict):\n                        references.extend(\n                            value for value in cameras.values()\n                            if isinstance(value, str) and value.strip()\n                        )\n                    for key in ("synchronized_frames_path", "tactile_events_path"):\n                        value = row.get(key)\n                        if isinstance(value, str) and value.strip():\n                            references.append(value)\n                    streams = row.get("tactile_stream_paths")\n                    if isinstance(streams, dict):\n                        for entry in streams.values():\n                            if isinstance(entry, dict):\n                                references.extend(\n                                    value for value in entry.values()\n                                    if isinstance(value, str) and value.strip()\n                                )\n                    if len(references) >= 12:\n                        break\n        except (OSError, json.JSONDecodeError):\n            return fallback\n\n        relative_references = [\n            Path(value)\n            for value in references\n            if not Path(value).expanduser().is_absolute()\n        ]\n        if not relative_references:\n            return fallback\n\n        candidates = [fallback, *manifest_path.resolve().parents]\n        best_root = fallback\n        best_score = -1\n        seen: set[Path] = set()\n        for candidate in candidates:\n            candidate = candidate.resolve()\n            if candidate in seen:\n                continue\n            seen.add(candidate)\n            score = sum((candidate / value).exists() for value in relative_references)\n            if score > best_score:\n                best_root = candidate\n                best_score = score\n            if score == len(relative_references):\n                break\n        return best_root if best_score > 0 else fallback\n')
replace_once("webui/server.py", '    def source_file(self, value: Any, suffix: str | None = None) -> Path:\n        if not isinstance(value, str) or not value.strip():\n            raise ValueError("missing source-project-relative path")\n        raw = Path(value).expanduser()\n        path = raw.resolve() if raw.is_absolute() else (self.source_root / raw).resolve()\n        try:\n            path.relative_to(self.source_root)\n        except ValueError as exc:\n            raise ValueError("source data path escapes source project root") from exc\n        if suffix and path.suffix.lower() != suffix.lower():\n            raise ValueError(f"expected {suffix} file")\n        return path\n', '    def source_file(self, value: Any, suffix: str | None = None) -> Path:\n        if not isinstance(value, str) or not value.strip():\n            raise ValueError("missing source-project-relative path")\n        raw = Path(value).expanduser()\n        path = raw.resolve() if raw.is_absolute() else (self.data_root / raw).resolve()\n        try:\n            path.relative_to(self.data_root)\n        except ValueError as exc:\n            raise ValueError("source data path escapes resolved data root") from exc\n        if suffix and path.suffix.lower() != suffix.lower():\n            raise ValueError(f"expected {suffix} file")\n        return path\n')
replace_once(
    "webui/server.py",
    "(path for path in self.source_root.glob(pattern) if path.is_file())",
    "(path for path in self.data_root.glob(pattern) if path.is_file())",
)
replace_once(
    "webui/server.py",
    'row.setdefault("manifest_source", self._display_path(self.manifest_path, self.source_root))',
    'row.setdefault("manifest_source", self._display_path(self.manifest_path, self.data_root))',
)

test_path = Path("webui/tests/test_workspace.py")
test_text = test_path.read_text(encoding="utf-8")
needle = "    def test_rejects_invalid_interval(self):\n"
if needle not in test_text:
    raise SystemExit("test insertion point not found")
new_test = '    def test_symlinked_manifest_infers_original_project_root(self):\n        temporary, app = self.make_app()\n        self.addCleanup(temporary.cleanup)\n        external_temporary = tempfile.TemporaryDirectory()\n        self.addCleanup(external_temporary.cleanup)\n        external = Path(external_temporary.name)\n\n        old_manifest = (\n            external\n            / "datasets/lf3r_failure_rollouts/v1/failrecovery_manifest.jsonl"\n        )\n        old_manifest.parent.mkdir(parents=True)\n        video_rel = (\n            "datasets/lf3r_failure_rollouts/v1/"\n            "failrecovery/episode_001/videos/cam_high.mp4"\n        )\n        video = external / video_rel\n        video.parent.mkdir(parents=True)\n        video.write_bytes(b"video")\n        old_manifest.write_text(\n            json.dumps(\n                {\n                    "id": "usb_symlink",\n                    "task_key": "usb_insert",\n                    "total_frames": 1,\n                    "fps": 30,\n                    "camera_video_paths": {"cam_high": video_rel},\n                }\n            )\n            + "\\n"\n        )\n        seed = external / "outputs/usb_event_intervals/run/intervals.jsonl"\n        seed.parent.mkdir(parents=True)\n        seed.write_text(\n            json.dumps(\n                {\n                    "rollout_id": "usb_symlink",\n                    "event_key": 6,\n                    "start_frame": 0,\n                    "end_frame": 0,\n                }\n            )\n            + "\\n"\n        )\n\n        local_manifest = app.root / "datasets/failrecovery/manifest.jsonl"\n        local_manifest.unlink()\n        local_manifest.symlink_to(old_manifest)\n\n        app.save_settings({**app.settings, "source_project_root": "."})\n        self.assertEqual(app.manifest_path, old_manifest.resolve())\n        self.assertEqual(app.data_root, external.resolve())\n        self.assertEqual(app.source_file(video_rel), video.resolve())\n        self.assertEqual(app.annotation_seed_path(), seed.resolve())\n        self.assertIn("usb_symlink", app.rollout_map())\n\n'
test_path.write_text(test_text.replace(needle, new_test + needle, 1), encoding="utf-8")

readme = Path("README.md")
text = readme.read_text(encoding="utf-8")
old_para = 'Do not symlink the dataset tree when the manifest contains paths relative to the original project root. In **Settings → Source project root**, point directly to that original project (for example `/mnt/hdd/pyr/LF3R`). The WebUI uses `datasets/failrecovery/manifest.jsonl` in this standalone repository. For an unmigrated dissertation source, it also accepts the legacy `datasets/lf3r_failure_rollouts/v1/failrecovery_manifest.jsonl` and resolves every exported relative video/tactile path against the same source root. The standalone repository keeps its own annotations and experiment outputs.\n'
new_para = 'The fail-recovery payload does not need to be copied. `datasets/failrecovery/manifest.jsonl` may be a symlink to the original LF3R manifest. When it is linked, the WebUI resolves the symlink target, inspects the project-relative paths stored in that manifest, and automatically infers the original source-project root. Video, synchronization, tactile-event, tactile-stream, and historical interval-seed paths therefore continue to resolve against the original LF3R tree while new annotations stay local to this repository.\n'
if old_para in text:
    text = text.replace(old_para, new_para, 1)
text = text.replace(
    "To make this repository self-contained from the dissertation/LF3R project, run:",
    "To connect this repository to an existing dissertation/LF3R data tree without copying the payload, run:",
)
text = text.replace(
    "The script copies the exported fail-recovery dataset into the flat layout, rewrites manifest paths that still contain `/v1/`, migrates annotation records/events and USB interval seeds, and copies the encoder checkpoints plus the two external tactile repositories when present. It does not copy virtual environments, raw recorder SQLite data, or historical generated SHARPA runs.",
    "The script links `datasets/failrecovery/manifest.jsonl` to the original manifest and links optional large encoder/repository dependencies. The WebUI follows the manifest link to resolve the original project-relative data paths. New annotations remain writable and local under `annotations/failrecovery/`.",
)
readme.write_text(text, encoding="utf-8")
